#include "studio_dummy_body.h"
#include <filesystem>
#include <fstream>
#include <chrono>
#include <iostream>
#include <new>
static int failures=0;static long fail_after=-1;
void *operator new(size_t n){if(fail_after==0)throw std::bad_alloc();if(fail_after>0)--fail_after;if(auto p=malloc(n?n:1))return p;throw std::bad_alloc();}
void *operator new[](size_t n){return ::operator new(n);}void operator delete(void *p) noexcept{free(p);}void operator delete[](void *p) noexcept{free(p);}void operator delete(void *p,size_t) noexcept{free(p);}void operator delete[](void *p,size_t) noexcept{free(p);}
#define CHECK(x) do{if(!(x)){std::cerr<<"FAIL "<<__LINE__<<": " #x " / "<<error<<"\n";++failures;}}while(0)
static std::string bytes(const std::filesystem::path &p){std::ifstream f(p,std::ios::binary);return {std::istreambuf_iterator<char>(f),{}};}
static void write(const std::filesystem::path &p,const std::string &s){std::ofstream f(p,std::ios::binary);f<<s;}
static std::unique_ptr<studio::Artwork> body(std::string &error,bool parts){auto art=studio::Artwork::create();for(int f=1;f<=7;++f)for(int kind=0;kind<(parts?2:1);++kind){auto name="LKDECAP"+std::string(parts?(kind?"TORSO":"LEG"):"")+std::to_string(f);int i=art->add_sprite(name,4,parts?2:4,0,error);if(i<0)return {};auto im=art->sprite(i);im->anix=2;im->aniy=parts?(kind?4:2):4;memset(im->data_p,parts?(kind?1:2):2,(size_t)4*im->h);}return art;}
static int dummy(const studio::SceneState &s){for(int i=0;i<(int)s.lanes.size();++i)if(s.lanes[i].name.find("Dummy body")==0)return i;return -1;}
static std::string wax(const std::filesystem::path &actor,const std::filesystem::path &source,int source_slots=20){auto slot="slot."+std::to_string(source_slots)+".";return "format=imgtool_world_project\nversion=1\ndoc.count=2\ndoc.0.path="+actor.u8string()+"\ndoc.1.path="+source.u8string()+"\nslot.count="+std::to_string(source_slots+4)+"\nslot.source_tabs="+std::to_string(source_slots)+"\nslot.0.doc_idx=0\nslot.0.sequence_frames=0\nslot.0.frame_delays=4\nstate.dummy_decap_body=1\nstate.dummy_decap_reset=0\nstate.dummy_decap_doc_idx=1\nstate.dummy_decap_doc_path="+source.u8string()+"\nstate.dummy_decap_prefix=LK\n"+slot+"zoom=2\n"+slot+"mirror=1\n"+slot+"local_dx=4\n"+slot+"local_dy=-6\n"+slot+"motion_dx=3\n"+slot+"frame_z=2\n"+slot+"frame_delays=48,6,6,10,10,10,10,10,10,6,6,6,6\n";}
int main(){using namespace studio;namespace fs=std::filesystem;std::string error;auto root=fs::temp_directory_path()/("studio-wax-dummy-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));fs::create_directories(root);auto actor=Artwork::demo(),whole=body(error,false),parts=body(error,true);CHECK(whole&&parts);if(!whole||!parts)return 1;CHECK(actor->save((root/"actor.IMG").u8string(),error)&&whole->save((root/"whole.IMG").u8string(),error)&&parts->save((root/"parts.IMG").u8string(),error));auto actor_bytes=bytes(root/"actor.IMG"),whole_bytes=bytes(root/"whole.IMG"),part_bytes=bytes(root/"parts.IMG");auto gen=actor->generation(),whole_gen=whole->generation(),part_gen=parts->generation();std::vector<SceneIssue> issues;auto source=[&](uint64_t uid){return uid==101?actor.get():uid==202?whole.get():uid==303?parts.get():nullptr;};
    for(int source_slots:{10,20})for(bool multipart:{false,true}){auto text=wax(root/"actor.IMG",root/(multipart?"parts.IMG":"whole.IMG"),source_slots);if(source_slots==10){auto pos=text.find("slot.source_tabs=");text.erase(pos,text.find('\n',pos)-pos+1);}auto path=root/"scene.WAX";write(path,text);auto project=SceneProject::read(path.u8string(),error);CHECK(project&&project->state.lanes.size()==2&&project->imported_wax());if(!project)continue;int lane=dummy(project->state);CHECK(lane>=0);if(lane<0)continue;auto &before=project->state.lanes[lane];CHECK(before.frames.size()==13&&before.magnification==2&&before.flip_x&&before.frames[0].x==4&&before.frames[0].y==6&&before.frames[0].vx==-3&&before.frames[0].ticks==48&&before.frames[1].ticks==6&&before.frames[0].pieces[0].key=="wax-dummy:LK");auto id=before.id,frame_id=before.frames[0].id;auto binding=[&](int a,const SceneAsset &){return a?SceneBinding{multipart?303ull:202ull,multipart?parts.get():whole.get()}:SceneBinding{101,actor.get()};};CHECK(project->bind(binding,issues));CHECK(project->state.lanes[lane].frames[0].pieces.size()==(multipart?2:1)&&project->state.lanes[lane].frames[0].name=="LKDECAP1"&&project->state.lanes[lane].id==id);CHECK(project->state.lanes[lane].frames[0].pieces[0].name==(multipart?"LKDECAPLEG1":"LKDECAP1"));CHECK(project->bind(binding,issues)&&project->state.lanes[lane].frames[0].name=="LKDECAP1");project->establish_loaded();CHECK(project->dirty()&&!project->can_undo());auto out=root/"scene.ISTUDIO";CHECK(project->save(out.u8string(),source,error));auto saved=bytes(out);CHECK(saved.find("wax-dummy:")==std::string::npos&&saved.find("version=5\n")!=std::string::npos);auto loaded=SceneProject::read(out.u8string(),error);CHECK(loaded&&loaded->bind(binding,issues));if(loaded){CHECK(loaded->state.lanes[lane].frames[0].pieces.size()==(multipart?2:1)&&loaded->state.lanes[lane].frames[0].id==frame_id&&loaded->save(out.u8string(),source,error)&&bytes(out)==saved);CHECK(loaded->export_png((root/"body.png").u8string(),0,source,error));}CHECK(bytes(path)==text);}
    auto text=wax(root/"actor.IMG",root/"whole.IMG");write(root/"base.WAX",text);auto load=[&](){return SceneProject::read((root/"base.WAX").u8string(),error);};auto binding=[&](int a,const SceneAsset &){return a?SceneBinding{202,whole.get()}:SceneBinding{101,actor.get()};};
    // Failed source binding never publishes an earlier successful dependency.
    auto missing=load();CHECK(missing&&!missing->bind([&](int a,const SceneAsset &){return a?SceneBinding{}:SceneBinding{101,actor.get()};},issues));if(missing){CHECK(missing->state.assets[0].runtime_doc==0&&missing->state.assets[1].runtime_doc==0&&missing->state.lanes[dummy(missing->state)].frames[0].pieces[0].key=="wax-dummy:LK"&&missing->bind(binding,issues));}
    auto incomplete=body(error,false);CHECK(incomplete->rename_sprite(7,"OTHER7",error));auto bad=load();CHECK(bad&&!bad->bind([&](int a,const SceneAsset &){return a?SceneBinding{202,incomplete.get()}:SceneBinding{101,actor.get()};},issues)&&!issues.empty());if(bad)CHECK(bad->state.assets[0].runtime_doc==0&&bad->bind(binding,issues));
    // Stock reset clears its timing/motion arrays, as classic's next draw does.
    auto reset=text;reset.replace(reset.find("dummy_decap_reset=0"),19,"dummy_decap_reset=1");write(root/"reset.WAX",reset);auto stock=SceneProject::read((root/"reset.WAX").u8string(),error);CHECK(stock);if(stock){auto &f=stock->state.lanes[dummy(stock->state)].frames[0];CHECK(f.ticks==48&&f.x==0&&f.y==0&&f.vx==0&&f.z==2);}
    auto effect=text+"slot.1.doc_idx=0\nslot.1.sequence_frames=0\nslot.1.frame_delays=3\nslot.1.hold=3\nslot.1.spawn_slot=20\nslot.1.spawn_entry=3\nslot.1.spawn_tick=60\nslot.1.visible_from=60\nslot.1.visible_until=63\n";write(root/"effect.WAX",effect);auto linked=SceneProject::read((root/"effect.WAX").u8string(),error);CHECK(linked&&linked->bind(binding,issues));if(linked){int effect_lane=-1;for(int i=0;i<(int)linked->state.lanes.size();++i)if(linked->state.lanes[i].trigger_lane)effect_lane=i;CHECK(effect_lane>=0&&scene_lane_start(linked->state,effect_lane)==60);}
    // Dummy-only scenes and inactive reserved slots must not create fake rows.
    auto only=text;auto pos=only.find("slot.0.doc_idx");auto end=only.find("state.dummy",pos);only.erase(pos,end-pos);only+="slot.21.doc_idx=0\nslot.21.sequence_frames=0\n";write(root/"only.WAX",only);auto single=SceneProject::read((root/"only.WAX").u8string(),error);CHECK(single&&single->state.lanes.size()==1&&single->state.assets.size()==1&&single->bind([&](int,const SceneAsset &){return SceneBinding{202,whole.get()};},issues));
    for(const std::string &setting:{"state.dummy_decap_doc_idx=-1\n","slot.20.frame_doc_idx=0\n","slot.20.spawn_slot=0\n"}){auto invalid=text;auto equal=setting.find('=');auto key=setting.substr(0,equal+1);auto at=invalid.find(key);if(at!=std::string::npos)invalid.erase(at,invalid.find('\n',at)-at+1);invalid+=setting;if(setting.find("doc_idx=-1")!=std::string::npos){auto a=invalid.find("state.dummy_decap_doc_path=");invalid.erase(a,invalid.find('\n',a)-a+1);}write(root/"bad.WAX",invalid);CHECK(!SceneProject::read((root/"bad.WAX").u8string(),error));}
    int rejected=0,succeeded=0;for(int n=0;n<1800;++n){auto target=load();CHECK(target);bool ok=false;fail_after=n;try{ok=target->bind(binding,issues);}catch(const std::bad_alloc &){}fail_after=-1;if(!ok){++rejected;CHECK(target->state.assets[0].runtime_doc==0&&target->state.assets[1].runtime_doc==0&&target->state.lanes[dummy(target->state)].frames[0].pieces[0].key=="wax-dummy:LK"&&!target->can_undo());}else{++succeeded;CHECK(target->state.assets[0].runtime_doc==101&&target->state.assets[1].runtime_doc==202);}}CHECK(rejected>20&&succeeded>0);
    CHECK(actor->generation()==gen&&whole->generation()==whole_gen&&parts->generation()==part_gen&&!actor->dirty()&&!whole->dirty()&&!parts->dirty()&&bytes(root/"actor.IMG")==actor_bytes&&bytes(root/"whole.IMG")==whole_bytes&&bytes(root/"parts.IMG")==part_bytes&&g_doc==nullptr);fs::remove_all(root);std::cout<<"WAX dummy import: "<<failures<<" failures\n";return failures?1:0;
}
